from datetime import datetime
from typing import Annotated

from pydantic import BaseModel, ConfigDict, EmailStr, Field, StringConstraints, field_validator

from app.models.enums import CardStatus, EngineerStatus
from app.schemas.common import Text

# Public engineer identifier ("ENG-0001"). Generated by the system; accepted as input only
# where an existing engineer is referenced.
EngineerCode = Annotated[str, StringConstraints(strip_whitespace=True, to_upper=True, pattern=r"^[Ee][Nn][Gg]-[0-9]{4,6}$")]

SETTABLE = (EngineerStatus.ACTIVE, EngineerStatus.INACTIVE, EngineerStatus.SUSPENDED)


def _settable(v: EngineerStatus) -> EngineerStatus:
    if v not in SETTABLE:
        raise ValueError("Estado no permitido (ELIMINADO solo se alcanza con el borrado de datos)")
    return v


class EngineerCreate(BaseModel):
    """The ``engineer_id`` (ENG-NNNN) is generated by the system, never supplied."""

    model_config = ConfigDict(extra="forbid")

    full_name: Text(3, 120)
    department: Text(2, 80)
    position: Text(2, 80)
    institutional_email: EmailStr
    status: EngineerStatus = EngineerStatus.ACTIVE

    _check_status = field_validator("status")(_settable)


class EngineerUpdate(BaseModel):
    """All optional. ``engineer_id`` is immutable; status changes go through ``/status``."""

    model_config = ConfigDict(extra="forbid")

    full_name: Text(3, 120) | None = None
    department: Text(2, 80) | None = None
    position: Text(2, 80) | None = None
    institutional_email: EmailStr | None = None


class EngineerStatusChange(BaseModel):
    model_config = ConfigDict(extra="forbid")

    status: EngineerStatus
    reason: Text(3, 300)

    _check_status = field_validator("status")(_settable)


class EngineerErase(BaseModel):
    model_config = ConfigDict(extra="forbid")

    confirm_engineer_id: EngineerCode  # must repeat the ID: protects against accidental erasure
    reason: Text(3, 300)


class CardBrief(BaseModel):
    model_config = ConfigDict(from_attributes=True)

    id: int
    uid: str
    status: CardStatus
    label: str | None


class EngineerOut(BaseModel):
    model_config = ConfigDict(from_attributes=True)

    id: int
    engineer_id: str
    full_name: str
    department: str
    position: str
    institutional_email: str
    face_embedding_reference: str | None
    registration_date: datetime
    status: EngineerStatus
    has_face: bool
    face_samples: int
    updated_at: datetime
    cards: list[CardBrief]


class StatusChangeResult(BaseModel):
    engineer: EngineerOut
    requests_revoked: int
    requests_rejected: int


class ErasureResult(BaseModel):
    engineer: EngineerOut
    requests_revoked: int
    requests_rejected: int
    cards_unlinked: int
    face_samples_deleted: int


class NextIdOut(BaseModel):
    engineer_id: str


# ------------------------------------------------------------------ biometrics (metadata only)
class FaceSampleOut(BaseModel):
    """Never includes the embedding itself."""

    model_config = ConfigDict(from_attributes=True)

    id: int
    model_name: str
    quality_score: float | None
    is_primary: bool
    created_at: datetime


class FaceProfileOut(BaseModel):
    face_embedding_reference: str | None
    samples: list[FaceSampleOut]
    min_samples: int
    max_samples: int


class QualityOut(BaseModel):
    ok: bool
    score: float
    issues: list[str]
    messages: list[str]
    face_count: int
    det_score: float | None = None
    face_px: int | None = None
    sharpness: float | None = None
    brightness: float | None = None
    yaw_ratio: float | None = None
    bbox: tuple[float, float, float, float] | None = None
    image_width: int | None = None
    image_height: int | None = None


class ImageReport(BaseModel):
    index: int
    filename: str | None
    accepted: bool
    quality: QualityOut | None = None
    error_code: str | None = None
    error: str | None = None


class EnrollmentOut(BaseModel):
    engineer: EngineerOut
    model_name: str
    samples_added: int
    samples_total: int
    replaced: bool
    images: list[ImageReport] = Field(default_factory=list)
